pub fn failure_buckets(results: &[BenchTaskResult]) -> BTreeMap<String, usize> {
    let mut buckets = BTreeMap::new();
    for result in results {
        if result.passed {
            continue;
        }
        let key = result
            .failure_reason
            .as_deref()
            .and_then(|reason| reason.split(':').next())
            .unwrap_or("unknown")
            .to_string();
        *buckets.entry(key).or_insert(0) += 1;
    }
    buckets
}

